CustomField.formula:
CASE(BLANKVALUE(Country_HQ__c,BillingCountry),
"United States",IF(ISBLANK(TEXT(State_HQ__c)),AMER_State_Region_Billing__c,AMER_State_Region_HQ__c),
"Canada",IF(CONTAINS($Label.Subregion_AMER_Canada_East,BLANKVALUE(TEXT(State_HQ__c),BillingState) + ";"),"AMER - Canada East",IF(CONTAINS($Label.Subregion_AMER_Canada_West,BLANKVALUE(TEXT(State_HQ__c),BillingState) + ";"),"AMER - Canada West","")),
IF(NOT(ISBLANK(BLANKVALUE(Country_HQ__c,BillingCountry))),
    IF(CONTAINS($Label.Subregion_EMEA_SEE,BLANKVALUE(Country_HQ__c,BillingCountry) + ";"),"EMEA - SEE",
        IF(CONTAINS($Label.Subregion_EMEA_CEE,BLANKVALUE(Country_HQ__c,BillingCountry) + ";"),IF(BLANKVALUE(Country_HQ__c,BillingCountry) = "Israel","EMEA - Israel","EMEA - CEE"),
            IF(CONTAINS($Label.Subregion_EMEA_MEA,BLANKVALUE(Country_HQ__c,BillingCountry) + ";"),"EMEA - MEA",
                IF(CONTAINS($Label.Subregion_EMEA_Africa,BLANKVALUE(Country_HQ__c,BillingCountry) + ";"),"EMEA - MEA",
                    IF(CONTAINS($Label.Subregion_EMEA_CIS,BLANKVALUE(Country_HQ__c,BillingCountry) + ";"),"EMEA - CIS",
                        IF(CONTAINS($Label.Subregion_EMEA_UKI,BLANKVALUE(Country_HQ__c,BillingCountry) + ";"),"EMEA - UKI",
                            IF(CONTAINS($Label.Subregion_EMEA_Nordics,BLANKVALUE(Country_HQ__c,BillingCountry) + ";"),"EMEA - Nordics",
                                IF(CONTAINS($Label.Subregion_EMEA_BeNeLux,BLANKVALUE(Country_HQ__c,BillingCountry) + ";"),"EMEA - BeNeLux",
                                    IF(CONTAINS($Label.Subregion_EMEA_DACH,BLANKVALUE(Country_HQ__c,BillingCountry) + ";"),"EMEA - DACH",
                                        ""
                                    )
                                )
                            )
                        )
                    )
                )
            )
        )
    ),
    ""
)
)
